#!/usr/bin/env bash
# check-bench-md.sh — every package shipping a *_bench_test.go MUST commit a
# BENCH.md report. The report stamps machine + toolchain so cross-box deltas
# can be evaluated honestly.
#
# Rule:
#   For each directory containing at least one *_bench_test.go file, a sibling
#   BENCH.md MUST exist. The report is regenerated by `make bench` (alias for
#   `make sdk-bench-md`).
#
# Freshness is intentionally NOT checked here — bench numbers depend on the
# hardware running them, so a fresh report from machine A is not
# automatically "better" than an older report from machine B. Presence is
# the contract; operators re-run `make bench` when the numbers matter (after
# perf-sensitive changes, before tagging a release, on a representative
# benchmark machine).
#
# Exit codes:
#   0 — every bench package documented
#   1 — at least one *_bench_test.go without a sibling BENCH.md

set -euo pipefail

WORKSPACE="${1:-${CLAUDE_PROJECT_DIR:-/workspace}}"
cd "$WORKSPACE"

missing=0

bench_dirs=$(find internal pkg -type f -name '*_bench_test.go' -print0 2>/dev/null \
    | xargs -0 -n1 dirname \
    | sort -u \
    || true)

while IFS= read -r dir; do
    [ -z "$dir" ] && continue
    if [ ! -f "$dir/BENCH.md" ]; then
        echo "✘ $dir — has *_bench_test.go but no BENCH.md"
        missing=1
    fi
done <<< "$bench_dirs"

if [ "$missing" -ne 0 ]; then
    echo ""
    echo "Pre-commit: benchmark documentation policy violated."
    echo "  Every package shipping a *_bench_test.go MUST commit a BENCH.md report"
    echo "  alongside it. Regenerate with: make bench"
    exit 1
fi

exit 0
